def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    vowel_shift = {'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
                  'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'}

    result = []
    for char in message:
        if char.isalpha():
            # Determine original case
            is_upper = char.isupper()
            base_char = char.lower()

            if base_char in vowels:
                # Replace vowel with shifted vowel
                shifted = vowel_shift[base_char]
                # Apply case swap
                if is_upper:
                    shifted = shifted.upper()
                else:
                    shifted = shifted.lower()
                result.append(shifted)
            else:
                # For non-vowels, just swap case
                if is_upper:
                    result.append(base_char)
                else:
                    result.append(base_char.upper())
        else:
            # Non-alphabetic characters remain unchanged
            result.append(char)

    return ''.join(result)
